import{_ as a,o as t,c as o,a5 as c}from"./chunks/framework.C588jwcu.js";const u=JSON.parse('{"title":"場景化資源","description":"","frontmatter":{"title":"場景化資源","order":8},"headers":[],"relativePath":"tc/latest/tutorial/core/scene-assets.md","filePath":"tc/latest/tutorial/core/scene-assets.md","lastUpdated":1785683504000}'),s={name:"tc/latest/tutorial/core/scene-assets.md"};function r(d,e,n,_,i,l){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="場景化資源" tabindex="-1">場景化資源 <a class="header-anchor" href="#場景化資源" aria-label="Permalink to &quot;場景化資源&quot;">​</a></h1><p>角色與背景項目現在參照 <code>PackedScene</code>。場景中可以放置圖片、影片、Spine、Live2D、shader 或自訂節點。</p><p>角色場景應繼承 <code>KND_CharacterSceneBase</code>，並覆寫 <code>_apply_status(resolved_status_name, original_status_name)</code> 來套用狀態；系統會透過 <code>apply_status(status_name)</code> 呼叫它。<code>actor change</code> 預設會在角色掛載層上依序執行淡出、套用狀態和淡入，不會複製角色場景。轉場完成後才會繼續執行劇情，詳細設定請參閱<a href="./../script/actor/actor-change-state.html">演員切換狀態</a>。舞台動作應放在 <code>KND_ActorMotionLayer</code> 場景，其動畫名稱需與 KS 動作名稱一致。</p><p>背景場景應繼承 <code>KND_BackgroundSceneBase</code>。如需使用鏡頭指令，請加入名稱唯一的 <code>KonadoCamera2D</code>。內建轉場由 <code>KND_BackgroundTransitionLayer</code> 處理。</p>',4)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
